var cellSize = 50

class HexCell {
	constructor(x, y) {
		this.position = createVector(x, y)

		const cornerAngles = {
			left: PI,
			right: 0,
			topRight: -PI / 3,
			topLeft: -2 * PI / 3,
			bottomRight: PI / 3,
			bottomLeft: 2 * PI / 3,
		}

		for (const key in cornerAngles) {
			this[key] = () => createVector(
				this.position.x + cellSize * cos(cornerAngles[key]),
				this.position.y + cellSize * sin(cornerAngles[key])
			)
		}
	}

	center() {
		return this.position.copy()
	}

	cellAbove(n = 1) {
		let cell = this
		for (let i = 0; i < n; i++) {
			let pos = cell.topLeft()
			cell = new HexCell(pos.x, pos.y)
			pos = cell.topRight()
			cell = new HexCell(pos.x, pos.y)
		}
		return cell
	}

	cellAboveLeft(n = 1) {
		var cell = this
		for (let i = 0; i < n; i++) {
			var pos = cell.left()
			cell = new HexCell(pos.x, pos.y)
			pos = cell.topLeft()
			cell = new HexCell(pos.x, pos.y)
		}
		return cell
	}

	cellAboveRight(n = 1) {
		var cell = this
		for (let i = 0; i < n; i++) {
			var pos = cell.right()
			cell = new HexCell(pos.x, pos.y)
			pos = cell.topRight()
