		}
		return cell
	}

	cellBelow(n = 1) {
		var cell = this
		for (let i = 0; i < n; i++) {
			var pos = cell.bottomLeft()
			cell = new HexCell(pos.x, pos.y)
			pos = cell.bottomRight()
			cell = new HexCell(pos.x, pos.y)
		}
		return cell
	}

	cellBelowLeft(n = 1) {
		var cell = this
