			var pos = cell.left()
			cell = new HexCell(pos.x, pos.y)
			pos = cell.bottomLeft()
			cell = new HexCell(pos.x, pos.y)
		}
		return cell
	}

	cellBelowRight(n = 1) {
		var cell = this
