var stepTime = 2000 // ms

var buffer
function setup() {
	createCanvas(600, 600, WEBGL)
	buffer = createGraphics(900, 900)
}

function draw() {
	background(0)

	const time = millis()

	const linearStepProgress = (time % stepTime) / stepTime
  const stepProgress = Ease.easeInOutCubic(linearStepProgress)
	const linearTwoStepProgress = (time % (2*stepTime)) / (2*stepTime)
  const stepSide = (time % (2*stepTime)) >= stepTime ? -1 : 1

	buffer.clear()
	buffer.push()
	buffer.background('#702d28')
	buffer.translate(0, (-1+stepProgress) * 4*cellSize)
	for (let col = 0; col < 6; col++) {
		const hexes = []
		buffer.noFill()
		buffer.stroke('#db8344')
		buffer.strokeWeight(8)
		buffer.beginShape()
		for (let row = 0; row < 12; row++) {
			for (const [xOff, yOff] of [[0,0], [1.5*cellSize,cellSize]]) {
				const center = new HexCell(col*cellSize*3.2+xOff, row*cellSize*2+yOff)
				hexes.push({ cell: center, xOff })
				let points
				if (xOff === 0) {
					points = [
						p5.Vector.lerp(
							p5.Vector.lerp(
								center.right(),
								center.topRight(),
								0.9
							),
							center.center(),
							0//0.1
						),
						p5.Vector.lerp(
							center.topRight(),
							center.center(),
							0.1
						),
						p5.Vector.lerp(
							center.topLeft(),
							center.center(),
							0.1
						),
						p5.Vector.lerp(
							center.left(),
							center.center(),
							0.1
						),
						p5.Vector.lerp(
							center.bottomLeft(),
							center.center(),
							0.1
						),
						p5.Vector.lerp(
							center.bottomRight(),
							center.center(),
							0.1
						),
						p5.Vector.lerp(
							p5.Vector.lerp(
								center.right(),
								center.bottomRight(),
								0.9
							),
							center.center(),
							0//0.1
						),
					]
				} else {
					points = [
						p5.Vector.lerp(
							p5.Vector.lerp(
								center.left(),
								center.topLeft(),
								0.9
							),
							center.center(),
							0//0.1
						),
						p5.Vector.lerp(
							center.topLeft(),
							center.center(),
							0.1
						),
						p5.Vector.lerp(
							center.topRight(),
							center.center(),
							0.1
						),
						p5.Vector.lerp(
							center.right(),
							center.center(),
							0.1
						),
						p5.Vector.lerp(
							center.bottomRight(),
							center.center(),
							0.1
						),
						p5.Vector.lerp(
							center.bottomLeft(),
							center.center(),
							0.1
						),
						p5.Vector.lerp(
							p5.Vector.lerp(
								center.left(),
								center.bottomLeft(),
								0.9
							),
							center.center(),
							0//0.1
						),
					]
				}
				for (const { x, y } of points) {
					buffer.vertex(x, y)
				}
			}
		}
		buffer.endShape()

		buffer.noStroke()
		buffer.fill('#cf4c4c')
		for (const { cell, xOff } of hexes) {
			const off = (xOff === 0 ? 1 : -1) * cellSize/15
			buffer.beginShape()
			for (const dir of ['topLeft', 'topRight', 'right', 'bottomRight', 'bottomLeft', 'left']) {
				const { x, y } = p5.Vector.lerp(cell[dir](), cell.center(), 0.5)
				buffer.vertex(x + off, y)
			}
			buffer.endShape(CLOSE)
		}
	}
	buffer.pop()

	ambientLight(100)
	pointLight(255, 255, 255, 0, -100, -100)

	translate(0, -70, 100)
	rotateX(PI/5)
	rotateZ(cos(linearTwoStepProgress*TWO_PI)*PI/24)
	scale(1, 1, -1)
	texture(buffer)
	rectModerect(0, 0, buffer.width, buffer.height)
}
